"""FC27 market activity is generated by 659 independent club decisions."""
import sqlite3
import unittest
import hashlib

from world_fc27_market_schedule import (
    VERSION,FC27_SLOT_BASE,club_market_interest,fc27_market_slot,
    initialise_fc27_market_schedule,is_fc27_market)
from world_fc27_decision_audit import (
    initialize_decision_audit,save_negotiation,save_evaluations,
    shortlist_country_mix)
# The unit suite runs without the Flask web dependency; reproduce the
# exact deterministic stable hash without importing the live web module.
MARKET_MOMENTS=range(12)
def _stable(*parts):
    raw="|".join(str(p) for p in parts).encode("utf8")
    return int.from_bytes(hashlib.sha256(raw).digest()[:8],"big")


class ClubLedMarketTests(unittest.TestCase):
    def test_every_club_has_independent_non_forced_intent(self):
        ambitions=[45,65,87]
        def outcomes(window_seed,scenario):
            return {club for interval in range(len(MARKET_MOMENTS))
                for club in range(1,660)
                if club_market_interest(priority=ambitions[club%3]+10,
                    profile={"ambition_level":ambitions[club%3]},
                    draw=_stable(window_seed,interval,club,VERSION,"scout")%1000000,
                    activity_scale_qa=scenario)}
        baseline=outcomes("season-one",1)
        other=outcomes("another-window",1)
        expanded=outcomes("season-one",3)
        self.assertGreater(len(baseline),0)
        self.assertLess(len(baseline),659)
        self.assertNotEqual(baseline,other)
        self.assertGreater(len(expanded),len(baseline))
        # This is merely the set of participating clubs, not a target
        # count for the number of completed market transfers.

    def test_more_urgency_and_ambition_increases_interest_not_guarantees(self):
        a={"ambition_level":30}
        b={"ambition_level":95}
        weak=sum(club_market_interest(priority=0,profile=a,draw=i)
                 for i in range(0,1000000,1000))
        strong=sum(club_market_interest(priority=100,profile=b,draw=i)
                   for i in range(0,1000000,1000))
        self.assertGreater(strong,weak)
        self.assertLess(strong,1000)

    def test_high_ambition_enters_market_more_without_mandated_deals(self):
        ordinary={"ambition_level":58,"pressure_to_improve":58,
                  "financial_pressure_index":30}
        aggressive={**ordinary,"ambition_level":92,
                    "pressure_to_improve":85}
        probability=lambda profile:sum(club_market_interest(
            priority=50,profile=profile,draw=draw)
            for draw in range(0,1000000,1000))
        self.assertGreater(probability(aggressive),probability(ordinary))
        self.assertGreater(probability(aggressive),0)
        self.assertLess(probability(aggressive),1000)
        strained={**aggressive,"financial_pressure_index":96}
        self.assertLess(probability(strained),probability(aggressive))

    def test_unresolved_real_scouting_needs_build_without_guaranteed_action(self):
        profile={"ambition_level":84,"pressure_to_improve":85,
                 "financial_pressure_index":30}
        hits=lambda passes:sum(club_market_interest(
            priority=75,profile=profile,draw=draw,
            unattended_intervals=passes)
            for draw in range(0,1000000,1000))
        self.assertGreater(hits(8),hits(0))
        self.assertLess(hits(12),1000)
        self.assertGreater(hits(12),hits(8))
        with self.assertRaises(ValueError):
            club_market_interest(priority=75,profile=profile,
                draw=10,unattended_intervals=-1)

    def test_failure_categories_distinguish_player_refusal_and_agent_error(self):
        from world_fc27_decision_audit import classify_negotiation_failure
        self.assertEqual(classify_negotiation_failure(
            "agent_quote",ValueError("Player will not open agent talks: no role")),
            "player_refused_agent_talks")
        self.assertEqual(classify_negotiation_failure(
            "agent_first_response",ValueError("agent terms failed")),
            "agent_negotiation_failure")
        self.assertEqual(classify_negotiation_failure(
            "seller_model",ValueError("invalid seller facts")),
            "seller_or_offer_evaluation_failure")

    def test_each_club_and_interval_has_stable_non_colliding_checkpoint(self):
        slots={fc27_market_slot(index,club) for index in range(12)
               for club in range(1,660)}
        self.assertEqual(len(slots),12*659)
        self.assertGreater(min(slots),FC27_SLOT_BASE)
        self.assertEqual(fc27_market_slot(7,99),fc27_market_slot(7,99))
        with self.assertRaises(ValueError):
            fc27_market_slot(0,1000000)

    def test_planner_tables_are_persistable_and_idempotent(self):
        con=sqlite3.connect(":memory:")
        try:
            initialise_fc27_market_schedule(con)
            initialise_fc27_market_schedule(con)
            con.execute("""INSERT INTO world_fc27_market_intervals
                VALUES(3,2,659,12,1,'2026-08-01T12:00:00+00:00')""")
            con.execute("""INSERT INTO world_fc27_market_club_intents
                (window_id,interval_index,club_id,source_priority)
                VALUES(3,2,27,77)""")
            with self.assertRaises(sqlite3.IntegrityError):
                con.execute("""INSERT INTO world_fc27_market_club_intents
                    (window_id,interval_index,club_id,source_priority)
                    VALUES(3,2,27,77)""")
        finally:
            con.close()

    def test_older_worlds_never_enter_fc27_schedule(self):
        con=sqlite3.connect(":memory:")
        try:
            con.execute("""CREATE TABLE world_career_saves(
                career_id TEXT,dataset_id TEXT)""")
            con.execute("""INSERT INTO world_career_saves VALUES(
                'legacy','england-2026')""")
            self.assertFalse(is_fc27_market(con,career_id="legacy"))
        finally:
            con.close()

    def test_each_club_funnel_is_saved_without_affecting_market(self):
        con=sqlite3.connect(":memory:")
        try:
            initialize_decision_audit(con)
            save_evaluations(con,[
                (9,2,11,72,90202,403,"proceeded_to_search"),
                (9,2,12,62,779500,403,"did_not_scout")])
            self.assertEqual(con.execute("""SELECT stage FROM
                world_fc27_market_club_evaluations WHERE club_id=12"""
                ).fetchone()[0],"did_not_scout")
            save_negotiation(con,window_id=9,interval_index=2,
                club_id=11,result_stage="shortlist_ready",
                eligible_candidates=4,same_country_candidates=1,
                foreign_country_candidates=3,search_family="DEF")
            save_negotiation(con,window_id=9,interval_index=2,
                club_id=11,result_stage="player_not_interested",
                reason="Sporting downgrade")
            row=con.execute("""SELECT result_stage,reason,
                eligible_candidates,same_country_candidates,
                foreign_country_candidates,search_family
                FROM world_fc27_market_negotiation_diagnostics
                WHERE window_id=9 AND club_id=11""").fetchone()
            self.assertEqual(row,("player_not_interested",
                "Sporting downgrade",4,1,3,"DEF"))
            with self.assertRaises(ValueError):
                save_negotiation(con,window_id=9,interval_index=2,
                    club_id=11,result_stage="bad",invented_personality=10)
        finally:
            con.close()

    def test_foreign_candidate_share_is_a_pool_measure_not_preference(self):
        eligible=[(13,100),(14,101),(14,102),(15,103),(16,104)]
        countries={1:"England",13:"England",14:"France",
                   15:"Portugal",16:"France"}
        mix=shortlist_country_mix(options=eligible,buyer=1,
                                  countries=countries)
        self.assertEqual(mix["same_country_candidates"],1)
        self.assertEqual(mix["foreign_country_candidates"],4)
        self.assertEqual(mix["unknown_country_candidates"],0)
        self.assertEqual(shortlist_country_mix(
            options=eligible,buyer=999,countries=countries)
            ["unknown_country_candidates"],5)

    def test_nothing_is_mathematically_fixed_to_112(self):
        from pathlib import Path
        text=Path("world_live_market.py").read_text()
        self.assertIn("if fc27_club_led:",text)
        self.assertIn("process_fc27_market_interval(",text)
        self.assertIn("else:\n            # IMMUTABLE older careers",text)
        from world_fc27_market_schedule import SCHEMA
        self.assertIn("active_clubs INTEGER",SCHEMA)


if __name__=="__main__":
    unittest.main()
